export default async function ({ username }, ctx) {
  if (typeof username !== "string" || !username.trim()) throw Error("Provide a creator username");
  async function load(file) {
    const chunks = [];
    let start = 0,
      total = 0,
      etag;
    do {
      const response = await ctx.fetch(
        "https://raw.githubusercontent.com/teds-tech-talks/n8n-community-leaderboard/refs/heads/main/" +
          file +
          ".json",
        {
          headers: {
            Range: `bytes=${start}-${start + 524287}`,
            ...(etag ? { "If-Range": etag } : {}),
          },
        },
      );
      if (response.status !== 206) throw Error("Leaderboard range request failed");
      const range = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(response.headers.get("content-range") || "");
      const tag = response.headers.get("etag");
      if (!range || +range[1] !== start || (etag && tag !== etag) || (total && +range[3] !== total))
        throw Error("Leaderboard changed during download");
      etag = tag;
      total = +range[3];
      const bytes = new Uint8Array(await response.arrayBuffer());
      if (bytes.length !== +range[2] - start + 1 || !bytes.length)
        throw Error("Incomplete leaderboard range");
      chunks.push(bytes);
      start += bytes.length;
    } while (start < total);
    const bytes = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) {
      bytes.set(chunk, offset);
      offset += chunk.length;
    }
    const data = JSON.parse(new TextDecoder().decode(bytes));
    if (!Array.isArray(data)) throw Error("Invalid leaderboard data");
    return data;
  }
  const creators = await load("stats_aggregate_creators"),
    workflows = await load("stats_aggregate_workflows");
  const creator = creators
    .sort((a, b) => (b.sum_unique_weekly_inserters || 0) - (a.sum_unique_weekly_inserters || 0))
    .slice(0, 25)
    .find((x) => x.user?.username === username);
  const selected = workflows
    .sort((a, b) => (b.unique_weekly_inserters || 0) - (a.unique_weekly_inserters || 0))
    .slice(0, 300)
    .filter((x) => x.user?.username === username);
  return {
    creator: creator || null,
    workflows: creator
      ? selected.map((x) => ({
          template_url: x.template_url,
          wf_detais: x.wf_detais,
          unique_weekly_inserters: x.unique_weekly_inserters,
          unique_monthly_inserters: x.unique_monthly_inserters,
          unique_weekly_visitors: x.unique_weekly_visitors,
          unique_monthly_visitors: x.unique_monthly_visitors,
        }))
      : [],
  };
}
